function validate([nums, m]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 100) return 'nums needs 1 to 100 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 100)) return 'Each value in nums is between 1 and 100.';
  if (!Number.isInteger(m) || m < 1 || m > 200) return 'm is between 1 and 200.';
  return null;
}

