function canSplitArray(nums, m) {
  // Interval DP: can[i][j] says whether nums[i..j] can be cut all the way down to single elements.
  const n = nums.length;
  const prefix = [0];
  for (const v of nums) prefix.push(prefix[prefix.length - 1] + v);
  const good = (i, j) => i === j || prefix[j + 1] - prefix[i] >= m;
  const can = Array.from({ length: n }, () => new Array(n).fill(false));
  for (let len = 1; len <= n; len++) {
    for (let i = 0; i + len - 1 < n; i++) {
      const j = i + len - 1;
      if (len === 1) { can[i][j] = true; continue; }
      for (let k = i; k < j && !can[i][j]; k++) {
        if (good(i, k) && good(k + 1, j) && can[i][k] && can[k + 1][j]) can[i][j] = true;
      }
    }
  }
  return can[0][n - 1];
}

