function generate(rand, size) {
  const n = size === 'large' ? 100 : 1 + Math.floor(rand() * 7);
  const top = size === 'large' ? 100 : 1 + Math.floor(rand() * 10);
  const nums = Array.from({ length: n }, () => 1 + Math.floor(rand() * top));
  let best = 0;
  for (let i = 0; i + 1 < n; i++) best = Math.max(best, nums[i] + nums[i + 1]);
  const r = rand();
  let m;
  if (r < 0.35 && best > 0) m = best;
  else if (r < 0.7 && best > 0) m = best + 1;
  else m = 1 + Math.floor(rand() * (size === 'large' ? 200 : 2 * top + 2));
  return [nums, Math.min(200, Math.max(1, m))];
}
